package dev.droidwrt.panel;
import android.view.*;import android.widget.*;import android.graphics.Typeface;import android.text.TextUtils;import org.json.*;
final class VpnCardView extends LinearLayout {
 final MainActivity owner;final TextView heading,direct;final Button directButton;final CoreTile mihomo,awg;final LinearLayout columns;final View divider;
 VpnCardView(MainActivity a){super(a);owner=a;setOrientation(VERTICAL);setPadding(a.dp(14),a.dp(12),a.dp(14),a.dp(12));setBackground(a.background(MainActivity.SURFACE,16));
  LinearLayout header=new LinearLayout(a);header.setGravity(Gravity.CENTER_VERTICAL);heading=a.text("VPN · подключения",12,MainActivity.MUTED);header.addView(heading,new LayoutParams(0,-2,1));header.addView(a.icon(R.drawable.ic_chevron,18));header.setPadding(0,0,0,a.dp(12));header.setContentDescription("VPN и маршруты");header.setFocusable(true);header.setOnClickListener(v->a.showEngines());addView(header);
  direct=a.text("Напрямую · новые соединения без VPN",12,MainActivity.MUTED);direct.setPadding(0,0,0,a.dp(10));addView(direct);
  FrameLayout split=new FrameLayout(a);columns=new LinearLayout(a);columns.setBaselineAligned(false);mihomo=new CoreTile("mihomo");awg=new CoreTile("awg");columns.addView(mihomo,new LayoutParams(0,-2,1));columns.addView(awg,new LayoutParams(0,-2,1));split.addView(columns,new FrameLayout.LayoutParams(-1,-2));divider=new View(a);divider.setBackgroundColor(MainActivity.LINE);split.addView(divider,new FrameLayout.LayoutParams(a.dp(1),-1,Gravity.CENTER_HORIZONTAL));addView(split);
  owner.gap(this,14);directButton=new Button(a);directButton.setText("Прямое подключение");directButton.setTextSize(14);directButton.setAllCaps(false);directButton.setStateListAnimator(null);a.styleSecondary(directButton);addView(directButton,new LayoutParams(-1,a.dp(48)));directButton.setOnClickListener(v->a.confirmDirect(()->a.showHome()));

 }
 final class CoreTile extends LinearLayout {
  final String engine;final TextView role,name,profile,address,ipv6,latency,state;
  CoreTile(String id){super(owner);engine=id;setOrientation(VERTICAL);setPadding(owner.dp(10),0,owner.dp(10),0);setGravity(Gravity.CENTER_HORIZONTAL);setFocusable(true);setOnClickListener(v->owner.showEngineProfiles(engine));role=owner.text("",10,MainActivity.ACCENT);role.setLetterSpacing(.06f);addView(role);owner.gap(this,9);
   LinearLayout identity=new LinearLayout(owner);identity.setGravity(Gravity.CENTER);ImageView mark=owner.icon(owner.engineIcon(id),26);mark.clearColorFilter();identity.addView(mark);name=owner.text(id.equals("awg")?"AWG":"Mihomo",16,MainActivity.FG);name.setTypeface(Typeface.create("sans-serif-medium",0));name.setPadding(owner.dp(7),0,0,0);identity.addView(name);addView(identity);owner.gap(this,8);
   profile=owner.text("",12,MainActivity.FG);profile.setSingleLine(true);profile.setEllipsize(TextUtils.TruncateAt.END);addView(profile);owner.gap(this,8);
   address=owner.text("",11,MainActivity.MUTED);address.setSingleLine(true);addView(address);owner.gap(this,6);ipv6=owner.text("IPv6 · проверяется",11,MainActivity.MUTED);ipv6.setMinLines(2);ipv6.setBreakStrategy(android.text.Layout.BREAK_STRATEGY_SIMPLE);addView(ipv6);owner.gap(this,6);latency=owner.text("",11,MainActivity.MUTED);addView(latency);owner.gap(this,8);state=owner.text("",11,MainActivity.ACCENT);addView(state);for(TextView label:new TextView[]{role,profile,address,ipv6,latency,state})label.setGravity(Gravity.CENTER);
  }
  void update(JSONObject r,JSONObject links,boolean fresh){String primary=r.optString("primary");boolean selected=primary.equals(engine),connected=fresh&&r.optString(engine+"_state").equals("connected");role.setText(selected?(r.optBoolean("automatic_reserve")?"АКТИВНЫЙ":"ОСНОВНОЙ"):r.optString("preferred").equals(engine)?"ОСНОВНОЙ":"РЕЗЕРВ");role.setTextColor(selected?MainActivity.ACCENT:MainActivity.MUTED);profile.setText(owner.profileName(r.optString(engine+"_profile")));String status=!fresh?"Нет свежих данных":connected?"● Подключён":r.optString(engine+"_state").equals("degraded")?"● Нестабильная сеть":r.optString(engine+"_state").equals("unresponsive")?"Нет ответа VPN":r.optString(engine+"_profile").isEmpty()?"Не настроен":"Подключается…";state.setText(status);state.setTextColor(connected?MainActivity.ACCENT:MainActivity.MUTED);
   JSONObject link=links.optJSONObject(engine);boolean current=fresh&&link!=null&&link.optString("state").equals("verified")&&link.optString("profile").equals(r.optString(engine+"_profile"))&&System.currentTimeMillis()/1000-link.optLong("checked_at")<=90;
   address.setText(current?owner.flag(link.optString("country"))+" "+link.optString("ip"):"IPv4 · нет данных");ipv6.setText(fresh?owner.ipv6Address(engine):"Нет свежих данных");latency.setText(current?"Отклик · "+link.optInt("latency_ms")+" мс":"Отклик · —");setContentDescription(name.getText()+", "+role.getText()+", "+profile.getText()+", "+status+", "+address.getText()+", "+ipv6.getText()+", "+latency.getText());
  }
 }
 void update(JSONObject status,boolean fresh){JSONObject r=status.optJSONObject("router"),links=status.optJSONObject("links");if(r==null)r=new JSONObject();if(links==null)links=new JSONObject();boolean isDirect=r.optString("primary").equals("direct");directButton.setText(isDirect&&fresh?"Прямое подключение активно":"Прямое подключение");directButton.setEnabled(fresh&&!isDirect);directButton.setAlpha(fresh&&!isDirect?1f:.55f);CoreTile first=r.optString("primary").equals("awg")?awg:mihomo,second=first==awg?mihomo:awg;if(columns.getChildAt(0)!=first){columns.removeAllViews();columns.addView(first,new LayoutParams(0,-2,1));columns.addView(second,new LayoutParams(0,-2,1));}boolean blocked=r.optString("primary").equals("blocked"),reserve=r.optBoolean("automatic_reserve");direct.setVisibility(isDirect||blocked||reserve?VISIBLE:GONE);if(blocked)direct.setText("Трафик заблокирован · восстанавливаем VPN");else if(reserve)direct.setText("Резерв активен · "+(r.optString("primary").equals("awg")?"AWG":"Mihomo"));if(isDirect)direct.setText("Напрямую · без VPN\n"+owner.connectionAddress("direct")+"\n"+owner.ipv6Address("direct"));mihomo.update(r,links,fresh);awg.update(r,links,fresh);}
}
